// Parses sensor01 telemetry, runs Layer-1 security checks and stores state in flow 's1'.
// Outputs: 1 = temperature (gauge + chart), 2 = state changed (-> Render Fridge), 3 = events (-> Event Log)
const events = [];
const log = (sev, text) => events.push({ sev, src: 'sensor01', text });

let d = msg.payload;
if (typeof d === 'string') {
    try { d = JSON.parse(d); } catch (e) { d = null; }
}
if (!d || typeof d !== 'object') {
    log('WARN', `Malformed telemetry dropped: ${String(msg.payload).slice(0, 60)}`);
    return [null, null, { events }];
}

// Retained messages are replayed by the broker on every reconnect: old data (or a planted
// spoof), never a live reading. Log it and do not let it refresh the watchdog or charts.
if (msg.retain) {
    log('WARN', `Ignored RETAINED telemetry (seq=${d.seq}): stale or planted message on broker`);
    return [null, null, { events }];
}

const prev = flow.get('s1') || {};

if (d.status === 'offline') {
    log('CRITICAL', 'Node 1 went OFFLINE (LWT triggered)');
    flow.set('s1', Object.assign({}, prev, { lwtOffline: true }));
    return [null, { topic: 'update' }, { events }];
}

const now = Date.now();
const temp = Number(d.temp);
const door = String(d.door || 'closed').toUpperCase();
const doorS = Number(d.door_open_s) || 0;
const alarm = d.alarm || 'NONE';

const lastSeq = flow.get('s1_last_seq');
if (d.fake === true || !Number.isFinite(temp) || temp < -20 || temp > 60) {
    log('CRITICAL', `Implausible/Spoofed reading detected (temp=${d.temp}C, seq=${d.seq})`);
} else if (lastSeq !== undefined && d.seq <= lastSeq && d.seq > 5) {
    log('WARN', `Replay or duplicate seq detected (${d.seq} <= ${lastSeq})`);
} else if (lastSeq !== undefined && d.seq > lastSeq + 1) {
    log('WARN', `Sequence gap: ${lastSeq} -> ${d.seq}`);
}
flow.set('s1_last_seq', d.seq);

const prevAlarm = flow.get('s1_prev_alarm');
if (alarm !== prevAlarm) {
    if (alarm !== 'NONE') {
        log(alarm === 'BREACH' ? 'CRITICAL' : 'WARN', `Alarm activated: ${alarm} (temp=${temp}C, door=${door})`);
    } else if (prevAlarm) {
        log('INFO', 'Alarm cleared (normal operation resumed)');
    }
    flow.set('s1_prev_alarm', alarm);
}

// Door-open start time, so the dashboard timer keeps counting between messages.
// Re-sync to the firmware's door_open_s only if we drift by more than 2 s.
let doorOpenedAt = null;
if (door === 'OPEN') {
    const fromDevice = now - doorS * 1000;
    doorOpenedAt = (prev.door === 'OPEN' && prev.doorOpenedAt && Math.abs(prev.doorOpenedAt - fromDevice) <= 2000)
        ? prev.doorOpenedAt : fromDevice;
}

flow.set('s1', { lastSeen: now, lwtOffline: false, temp, door, doorOpenedAt, alarm, seq: d.seq });

return [
    Number.isFinite(temp) ? { payload: temp } : null,
    { topic: 'update' },
    events.length ? { events } : null
];

// Parses sensor02 telemetry and stores state in flow 's2'.
// Outputs: 1 = mains 1/0 (chart), 2 = state changed (-> Render Power), 3 = events (-> Event Log)
const events = [];
const log = (sev, text) => events.push({ sev, src: 'sensor02', text });

let d = msg.payload;
if (typeof d === 'string') {
    try { d = JSON.parse(d); } catch (e) { d = null; }
}
if (!d || typeof d !== 'object') {
    log('WARN', `Malformed telemetry dropped: ${String(msg.payload).slice(0, 60)}`);
    return [null, null, { events }];
}

// Retained messages are replayed by the broker on every reconnect: old data (or a planted
// spoof), never a live reading. Log it and do not let it refresh the watchdog or charts.
if (msg.retain) {
    log('WARN', `Ignored RETAINED telemetry (seq=${d.seq}): stale or planted message on broker`);
    return [null, null, { events }];
}

const prev = flow.get('s2') || {};

if (d.status === 'offline') {
    log('CRITICAL', 'Node 2 Power Monitor OFFLINE (LWT / battery dead)');
    flow.set('s2', Object.assign({}, prev, { lwtOffline: true }));
    return [{ payload: 0 }, { topic: 'update' }, { events }];
}

const now = Date.now();
const mainsOn = String(d.mains).toLowerCase() === 'on';
const offS = Number(d.off_s) || 0;
if (prev.mainsOn !== mainsOn) {
    log(mainsOn ? 'INFO' : 'CRITICAL', mainsOn ? 'Mains power RESTORED' : 'Mains power CUT detected — running on backup');
}

// Power-cut start time so the cut timer keeps counting between messages (re-sync if > 2 s drift).
let cutAt = null;
if (!mainsOn) {
    const fromDevice = now - offS * 1000;
    cutAt = (prev.mainsOn === false && prev.cutAt && Math.abs(prev.cutAt - fromDevice) <= 2000) ? prev.cutAt : fromDevice;
}

flow.set('s2', { lastSeen: now, lwtOffline: false, mainsOn, cutAt, seq: d.seq });

return [{ payload: mainsOn ? 1 : 0 }, { topic: 'update' }, events.length ? { events } : null];

const isBreach = msg.payload === 'breach';
return { event: {
    sev: isBreach ? 'CRITICAL' : 'INFO',
    src: 'dashboard',
    text: `Operator sent '${msg.payload}' -> campus/sensor01/cmd`
} };

