// Renders Node 1 from flow 's1'. Runs on every update and on the 1 s tick, so the door timer counts
// live and the watchdog marks the node STALE / OFFLINE when it goes silent.
// Outputs: 1 = banner, 2 = temperature card, 3 = events (-> Event Log), 4 = health (-> status bar)
const cfg = flow.get('cfg');
const s = flow.get('s1') || {};
const now = Date.now();
const fmt = sec => `${Math.floor(sec / 60)}:${String(sec % 60).padStart(2, '0')}`;
const clock = t => new Date(t).toLocaleTimeString();

if (!context.get('since')) context.set('since', now);
const age = Math.floor((now - (s.lastSeen || context.get('since'))) / 1000);
const health = s.lwtOffline || age >= cfg.offlineS ? 'OFFLINE'
    : !s.lastSeen ? 'WAITING'
    : age >= cfg.staleS ? 'STALE' : 'ONLINE';

const events = [];
const prevHealth = context.get('health');
if (health !== prevHealth) {
    if (health === 'STALE') events.push({ sev: 'WARN', src: 'watchdog', text: `Node 1 telemetry STALE: no message for ${age} s` });
    if (health === 'OFFLINE' && !s.lwtOffline) events.push({ sev: 'CRITICAL', src: 'watchdog', text: `Node 1 OFFLINE: no message for ${age} s` });
    if (health === 'ONLINE' && (prevHealth === 'STALE' || prevHealth === 'OFFLINE')) events.push({ sev: 'INFO', src: 'watchdog', text: 'Node 1 back online' });
    context.set('health', health);
}

const RED = ['#7f1d1d', '#ef4444'], ORANGE = ['#7c2d12', '#f97316'], AMBER = ['#78350f', '#f59e0b'],
      BLUE = ['#1e3a8a', '#60a5fa'], GREEN = ['#064e3b', '#10b981'], GREY = ['#1e293b', '#64748b'];
const live = health === 'ONLINE' || health === 'STALE';
const doorSec = s.door === 'OPEN' && s.doorOpenedAt ? Math.max(0, Math.floor((now - s.doorOpenedAt) / 1000)) : 0;
const doorTxt = s.door === 'OPEN' ? `Door OPEN ${fmt(doorSec)}` : 'Door closed';
const t = Number.isFinite(s.temp) ? `${s.temp.toFixed(2)} °C` : '-- °C';
const lastData = s.lastSeen ? `last data ${clock(s.lastSeen)}` : 'no data since dashboard start';

// [colours, banner title, banner sub, short label for the temperature card]
let c, title, sub, label;
if (health === 'WAITING') {
    [c, title, sub, label] = [GREY, 'Waiting for Node 1...', `No telemetry yet · watchdog trips at ${cfg.offlineS} s`, 'WAITING'];
} else if (health === 'OFFLINE') {
    [c, title, sub, label] = [RED, 'NODE 1 OFFLINE', `${s.lwtOffline ? 'LWT received' : `Silent for ${fmt(age)}`} · ${lastData}`, 'OFFLINE'];
} else {
    if (s.alarm === 'BREACH') [c, title, sub, label] = [RED, 'SECURITY BREACH ACTIVE', `Buzzer + Red LED locked ON · seq #${s.seq}`, 'BREACH'];
    else if (s.temp < cfg.tempLowC) [c, title, sub, label] = [BLUE, `FREEZE RISK: BELOW ${cfg.tempLowC} °C`, `${t} · vaccines may be damaged · ${doorTxt}`, 'FREEZE'];
    else if (s.alarm === 'TEMP') [c, title, sub, label] = [ORANGE, 'OVER-TEMPERATURE ALARM', `${t} above ${cfg.tempHighC} °C for ${cfg.tempAlarmS} s+ · ${doorTxt}`, 'ALARM'];
    else if (s.temp > cfg.tempHighC) [c, title, sub, label] = [AMBER, `WARNING: ABOVE ${cfg.tempHighC} °C`, `${t} · alarm after ${cfg.tempAlarmS} s · ${doorTxt}`, 'WARNING'];
    else if (s.alarm === 'DOOR') [c, title, sub, label] = [ORANGE, `DOOR ALARM (${fmt(doorSec)})`, `Close vaccine fridge door · buzzer sounding · ${t}`, 'DOOR ALARM'];
    else if (s.door === 'OPEN') [c, title, sub, label] = [AMBER, `DOOR OPEN (${fmt(doorSec)})`, `Alarm at ${fmt(cfg.doorAlarmS)} · ${t}`, 'DOOR OPEN'];
    else [c, title, sub, label] = [GREEN, `COLD-CHAIN SAFE (${cfg.tempLowC}–${cfg.tempHighC} °C)`, `${t} · Door closed`, 'SAFE'];
    sub += ` · ${clock(s.lastSeen)}`;
    if (health === 'STALE') {
        title = `STALE DATA · ${title}`;
        sub = `No message for ${age} s · ${sub}`;
        c = [c[0], '#eab308'];
        label = 'STALE';
    }
}
if (cfg.bench) sub += ' · BENCH TIMING';
const b = { bg: c[0], bd: c[1], title, sub };

// Temperature card: big reading + position on a scale with the safe band highlighted.
const scale = [-5, cfg.bench ? 40 : 20];
const pct = v => Math.max(0, Math.min(100, (v - scale[0]) / (scale[1] - scale[0]) * 100));
const card = {
    live, label, color: c[1],
    temp: live && Number.isFinite(s.temp) ? s.temp : null,
    band: { lo: pct(cfg.tempLowC), hi: pct(cfg.tempHighC), pos: live && Number.isFinite(s.temp) ? pct(s.temp) : null },
    scale, low: cfg.tempLowC, high: cfg.tempHighC,
    door: live ? s.door : null,
    doorText: !live ? 'unknown' : s.door === 'OPEN' ? `OPEN ${fmt(doorSec)} (alarm at ${fmt(cfg.doorAlarmS)})` : 'CLOSED',
    note: live ? `updated ${age} s ago`
        : health === 'WAITING' ? 'waiting for first reading'
        : Number.isFinite(s.temp) ? `last ${s.temp.toFixed(1)} °C at ${clock(s.lastSeen)}` : 'no data since dashboard start'
};

const hl = {
    name: 'Node 1 · Fridge', health, bench: cfg.bench,
    label, color: c[1], temp: card.temp, door: card.door,   // for the System Overview diagram
    detail: health === 'ONLINE' ? `seq #${s.seq} · ${age} s ago`
        : health === 'STALE' ? `no data for ${age} s`
        : health === 'OFFLINE' ? (s.lwtOffline ? `LWT · ${lastData}` : lastData)
        : 'waiting'
};
// Status bar gets BOTH nodes in every message, so a newly opened page (which only receives the
// last message) always shows the full picture.
const allHealth = Object.assign({}, flow.get('nodeHealth'), { n1: hl });
flow.set('nodeHealth', allHealth);

// Only send what changed, so the 1 s tick does not flood the dashboard.
const changed = (key, v) => { const j = JSON.stringify(v); if (j === context.get(key)) return false; context.set(key, j); return true; };
return [
    changed('lastBanner', b) ? { payload: b } : null,
    changed('lastCard', card) ? { payload: card } : null,
    events.length ? { events } : null,
    changed('lastHealth', hl) ? { payload: allHealth } : null
];

// Renders Node 2 from flow 's2'. Runs on every update and on the 1 s tick:
// live power-cut timer and STALE / OFFLINE watchdog.
// Outputs: 1 = banner, 2 = health (-> status bar), 3 = events (-> Event Log)
const cfg = flow.get('cfg');
const s = flow.get('s2') || {};
const now = Date.now();
const fmt = sec => `${Math.floor(sec / 60)}:${String(sec % 60).padStart(2, '0')}`;
const clock = t => new Date(t).toLocaleTimeString();

if (!context.get('since')) context.set('since', now);
const age = Math.floor((now - (s.lastSeen || context.get('since'))) / 1000);
const health = s.lwtOffline || age >= cfg.offlineS ? 'OFFLINE'
    : !s.lastSeen ? 'WAITING'
    : age >= cfg.staleS ? 'STALE' : 'ONLINE';

const events = [];
const prevHealth = context.get('health');
if (health !== prevHealth) {
    if (health === 'STALE') events.push({ sev: 'WARN', src: 'watchdog', text: `Node 2 telemetry STALE: no message for ${age} s` });
    if (health === 'OFFLINE' && !s.lwtOffline) events.push({ sev: 'CRITICAL', src: 'watchdog', text: `Node 2 OFFLINE: no message for ${age} s (SR-14)` });
    if (health === 'ONLINE' && (prevHealth === 'STALE' || prevHealth === 'OFFLINE')) events.push({ sev: 'INFO', src: 'watchdog', text: 'Node 2 back online' });
    context.set('health', health);
}

const lastData = s.lastSeen ? `last data ${clock(s.lastSeen)}` : 'no data since dashboard start';
const banner = (c, title, sub) => ({ bg: c[0], bd: c[1], title, sub });
let b;
if (health === 'WAITING') {
    b = banner(['#1e293b', '#64748b'], 'Waiting for Node 2...', `No telemetry yet · watchdog trips at ${cfg.offlineS} s`);
} else if (health === 'OFFLINE') {
    b = banner(['#7f1d1d', '#ef4444'], 'NODE 2 OFFLINE (SR-14 ALERT)',
        `${s.lwtOffline ? 'LWT received' : `Silent for ${fmt(age)}`} · ${lastData}`);
} else {
    b = s.mainsOn
        ? banner(['#064e3b', '#10b981'], 'MAINS POWER ON (230 V OK)', `seq #${s.seq} · Node 2 healthy`)
        : banner(['#7f1d1d', '#ef4444'], `POWER CUT DETECTED (${fmt(Math.max(0, Math.floor((now - s.cutAt) / 1000)))})`,
            'Backup battery active · Buzzer sounding');
    if (health === 'STALE') {
        b.title = `STALE DATA · ${b.title}`;
        b.sub = `No message for ${age} s · ${b.sub}`;
        b.bd = '#eab308';
    }
}

const hl = {
    name: 'Node 2 · Power', health, bench: cfg.bench,
    mains: health === 'ONLINE' || health === 'STALE' ? (s.mainsOn ? 'ON' : 'CUT') : null,   // for the diagram
    detail: health === 'ONLINE' ? `seq #${s.seq} · ${age} s ago`
        : health === 'STALE' ? `no data for ${age} s`
        : health === 'OFFLINE' ? (s.lwtOffline ? `LWT · ${lastData}` : lastData)
        : 'waiting'
};
// Status bar gets BOTH nodes in every message, so a newly opened page (which only receives the
// last message) always shows the full picture.
const allHealth = Object.assign({}, flow.get('nodeHealth'), { n2: hl });
flow.set('nodeHealth', allHealth);

const changed = (key, v) => { const j = JSON.stringify(v); if (j === context.get(key)) return false; context.set(key, j); return true; };
return [
    changed('lastBanner', b) ? { payload: b } : null,
    changed('lastHealth', hl) ? { payload: allHealth } : null,
    events.length ? { events } : null
];

// Single owner of the SOC security event log, persisted in the 'file' context store.
// Inputs:  msg.events = [{sev, src, text}] or msg.event   -> append, broadcast newest VIEW rows + summary
//          msg.topic 'refresh' (SOC feed)    -> newest VIEW rows to that client only
//          msg.topic 'export'  (SOC feed)    -> all stored rows to that client only
//          msg.topic 'summary' (SOC summary) -> 24 h summary to that client only
// Outputs: 1 = SOC feed, 2 = SOC summary tiles
// Retention: 90 days and at most MAX rows (M12: no personal data is logged, only device events).
const KEEP_MS = 90 * 24 * 3600 * 1000, MAX = 1000, VIEW = 100, DAY_MS = 24 * 3600 * 1000;

let logs = flow.get('eventLog', 'file') || [];
const now = Date.now();

const summary = () => {
    const day = logs.filter(l => now - l.ts <= DAY_MS);
    const count = sev => day.filter(l => l.sev === sev).length;
    return { critical: count('CRITICAL'), warn: count('WARN'), info: count('INFO'), last: logs[0] || null };
};

if (msg.topic === 'export') return [{ topic: 'export', payload: logs, socketid: msg.socketid }, null];
if (msg.topic === 'refresh') return [{ topic: 'log', payload: logs.slice(0, VIEW), socketid: msg.socketid }, null];
if (msg.topic === 'summary') return [null, { topic: 'summary', payload: summary(), socketid: msg.socketid }];

const incoming = msg.events || (msg.event ? [msg.event] : []);
if (!incoming.length) return null;

for (const e of incoming) logs.unshift({ ts: now, sev: e.sev, src: e.src, text: e.text });
logs = logs.filter(l => now - l.ts <= KEEP_MS).slice(0, MAX);
flow.set('eventLog', logs, 'file');
node.status({ text: `${logs.length} events stored` });
return [{ topic: 'log', payload: logs.slice(0, VIEW) }, { topic: 'summary', payload: summary() }];

// Owns the fridge temperature log (last 24 h, one sample per minute), persisted in the 'file' store,
// and its 24 h statistics. The full-rate history stays in Mobius/MySQL.
// Inputs:  msg.payload = temperature (from Process Node 1; door/alarm/seq read from flow 's1')
//          msg.topic 'refresh' / 'export' (from the dashboard panel) -> reply to that client only
// Output:  {topic:'stats'} broadcast after each new sample, or the reply to refresh/export
const KEEP_MS = 24 * 3600 * 1000, EVERY_MS = 60 * 1000;
const cfg = flow.get('cfg');
let log = flow.get('fridgeLog', 'file') || [];

const stats = () => {
    const temps = log.map(r => r.temp).filter(Number.isFinite);
    if (!temps.length) return { count: 0, low: cfg.tempLowC, high: cfg.tempHighC };
    return {
        count: temps.length,
        min: Math.min(...temps),
        max: Math.max(...temps),
        avg: temps.reduce((a, b) => a + b, 0) / temps.length,
        outMin: temps.filter(v => v < cfg.tempLowC || v > cfg.tempHighC).length,   // 1 sample = 1 minute
        low: cfg.tempLowC, high: cfg.tempHighC
    };
};

if (msg.topic === 'export') return { topic: 'export', payload: log, socketid: msg.socketid };
if (msg.topic === 'refresh') return { topic: 'stats', payload: stats(), socketid: msg.socketid };

const now = Date.now();
if (log.length && now - log[log.length - 1].ts < EVERY_MS) return null;

const s = flow.get('s1') || {};
log.push({ ts: now, temp: msg.payload, door: s.door, alarm: s.alarm, seq: s.seq });
log = log.filter(r => now - r.ts <= KEEP_MS);
flow.set('fridgeLog', log, 'file');
node.status({ text: `${log.length} samples (24 h)` });
return { topic: 'stats', payload: stats() };

// Owns the power-cut history (last 24 h), persisted in the 'file' store, and its statistics.
// Inputs:  state update from Process Node 2 (reads flow 's2')
//          msg.topic 'refresh' (from the dashboard panel) -> reply to that client only
// Output:  {topic:'stats'} when a cut starts or ends, or the reply to refresh
const KEEP_MS = 24 * 3600 * 1000;
let cuts = flow.get('powerCuts', 'file') || [];
const now = Date.now();

const stats = () => {
    const dur = c => Math.round(((c.end || now) - c.start) / 1000);
    const open = cuts.find(c => !c.end);
    return {
        count: cuts.length,
        totalS: cuts.reduce((a, c) => a + dur(c), 0),
        longestS: cuts.reduce((a, c) => Math.max(a, dur(c)), 0),
        ongoingSince: open ? open.start : null,
        lastEnd: cuts.filter(c => c.end).map(c => c.end).pop() || null
    };
};

if (msg.topic === 'refresh') return { topic: 'stats', payload: stats(), socketid: msg.socketid };

const s = flow.get('s2') || {};
if (s.lwtOffline || typeof s.mainsOn !== 'boolean') return null;   // offline is not a power cut

const open = cuts.length && !cuts[cuts.length - 1].end;
if (!s.mainsOn && !open) cuts.push({ start: s.cutAt || now });
else if (s.mainsOn && open) cuts[cuts.length - 1].end = now;
else return null;

cuts = cuts.filter(c => !c.end || now - c.end <= KEEP_MS);
flow.set('powerCuts', cuts, 'file');
node.status({ text: `${cuts.length} cuts (24 h)` });
return { topic: 'stats', payload: stats() };
